"""Automations chrome + catalog translations (he/es/pt-BR/ar)."""
from __future__ import annotations

def unflatten(items: dict[str, str]) -> dict:
    out: dict = {}
    for path, value in items.items():
        cur = out
        parts = path.split(".")
        for part in parts[:-1]:
            cur = cur.setdefault(part, {})
        cur[parts[-1]] = value
    return out


def _split(rows: dict[str, tuple[str, str, str, str]]) -> dict[str, dict]:
    he, es, pt, ar = {}, {}, {}, {}
    for key, (h, e, p, a) in rows.items():
        he[key] = h
        es[key] = e
        pt[key] = p
        ar[key] = a
    return {
        "he": unflatten(he),
        "es": unflatten(es),
        "pt-BR": unflatten(pt),
        "ar": unflatten(ar),
    }


